import sys

sys.setrecursionlimit(10000)


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        u = int(data[2 + 3 * i])
        v = int(data[3 + 3 * i])
        w = int(data[4 + 3 * i])
        adj[u].append((v, w))

    def reachable(s):
        seen = {s}
        stack = [s]
        while stack:
            u = stack.pop()
            for v, _ in adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        return seen

    reach = [set()] + [reachable(s) for s in range(1, n + 1)]

    # 가장 작은 번호의 정점에서 시작하는 단순 사이클을 모두 센다
    on_negative = set()
    for c in range(1, n + 1):
        path = [c]
        used = [False] * (n + 1)
        used[c] = True

        def cycles(u, total):
            for v, w in adj[u]:
                if v == c:
                    if total + w < 0:
                        on_negative.update(path)
                elif v > c and not used[v]:
                    used[v] = True
                    path.append(v)
                    cycles(v, total + w)
                    path.pop()
                    used[v] = False

        cycles(c, 0)

    # 정점 1 에서 시작하는 단순 경로를 모두 센다
    best = {1: 0}
    used = [False] * (n + 1)
    used[1] = True

    def paths(u, total):
        for v, w in adj[u]:
            if not used[v]:
                if v not in best or total + w < best[v]:
                    best[v] = total + w
                used[v] = True
                paths(v, total + w)
                used[v] = False

    paths(1, 0)

    out = []
    for v in range(1, n + 1):
        if any(c in reach[1] and v in reach[c] for c in on_negative):
            out.append("-INF")
        elif v not in reach[1]:
            out.append("INF")
        else:
            out.append(str(best[v]))
    sys.stdout.write("\n".join(out) + "\n")


main()
